const SUBTYPES = {"Elemental":{"standard":["Fire","Water","Wind","Earth","Ice","Lightning","Metal","Magma","Sand","Crystal","Acid","Mud","Ash","Snow","Steam","Mist","Smoke","Wood","Storm","Sound","Oil","Obsidian","Clay","Magnetism","Salt"],"notable":[{"name":"Light","desc":"raw light, flashes and glare; not holy, unrelated to the Light Dormitory"},{"name":"Dark","desc":"absorbing light and warmth; not evil"}],"forbidden":[{"name":"Blightfire","desc":"fire that never goes out, poisoning land for generations"},{"name":"Salting","desc":"permanently killing soil, unlike ordinary Salt"},{"name":"Poison","desc":"toxins made to persist and spread, unlike Potion Crafting"},{"name":"Rot","desc":"decay that eats land and stone permanently"},{"name":"Weather","desc":"changing weather on a scale no one can control"}]},"Mystic":{"standard":["Creation","Telekinesis","Teleportation","Barrier","Gravity","Mending","Reinforcement","Duplication","Divination","Scrying","Portal","Transmutation","Resizing","Enchantment","Golemancy","Dispelling","Phasing","Warding"],"notable":[{"name":"Object Reading","desc":"an object's past by touch"},{"name":"Astral","desc":"star magic, strongest on Star Night"},{"name":"Spatial","desc":"folding space, bags bigger inside"},{"name":"Time","desc":"briefly slowing or speeding small objects, never people"},{"name":"Anchoring","desc":"fixing an object in place"},{"name":"Runecraft","desc":"spells written as symbols that activate later"},{"name":"Sealing","desc":"locking away objects, spells or creatures"}],"forbidden":[{"name":"Unmaking","desc":"deleting matter permanently"},{"name":"Puppetry","desc":"moving a living body against its will"},{"name":"Wringing","desc":"telekinetic torture inside the body"},{"name":"Soul","desc":"treating the soul as material"},{"name":"Raise Dead","desc":"forcing a corpse to move"}]},"Spiritual":{"standard":["Healing","Strength","Speed","Endurance","Reflexes","Heightened Senses","Focus","Sleep","Regeneration","Purification","Recovery","Toughness","Adaptation","Pain Suppression","Berserk","Warcry","Empathy","Calm"],"notable":[{"name":"Stabilize","desc":"keeping the dying alive until a healer comes"},{"name":"Resuscitation","desc":"restarting a heart, legal only within minutes of death"},{"name":"Rest","desc":"a full night's sleep compressed into an hour"},{"name":"Aura","desc":"projected presence that intimidates or inspires"},{"name":"Willshield","desc":"resisting charms and mind control by will alone"},{"name":"Lifesense","desc":"sensing living beings nearby"},{"name":"Sharing","desc":"lending your own strength to someone else, the legal opposite of Drawing"}],"forbidden":[{"name":"Burning","desc":"spending your own lifespan as power"},{"name":"Drawing","desc":"taking another's will as fuel"},{"name":"Mind Control","desc":"overriding decisions"},{"name":"Slavery","desc":"permanent magical obedience"},{"name":"Effigy","desc":"curses worked through a proxy object"}]},"Occult":{"standard":["Illusion","Invisibility","Exorcism","Luck","Silence","Fear","Charm","Curse Breaking","Spirit Sight","Spirit Speech","Banishing","Shadow","Glamour","Dreamwalking"],"notable":[{"name":"Misdirection","desc":"making people overlook something"},{"name":"Jinx","desc":"brief minor bad luck"},{"name":"Oath","desc":"a magically enforced promise both sides agree to"},{"name":"Talisman","desc":"paper charms holding a stored spell"},{"name":"Ritual Circle","desc":"slow but powerful magic drawn on the ground"},{"name":"Spirit Binding","desc":"capturing and commanding"},{"name":"Spirit Pact","desc":"a lasting legal contract with one spirit"},{"name":"Familiar","desc":"a spirit bonded as an animal companion"},{"name":"Summoning","desc":"calling one already bound"},{"name":"Guardian Spirit","desc":"bound to protect a place"},{"name":"Name Binding","desc":"control through a spirit's true name"}],"forbidden":[{"name":"Demon Summoning","desc":"calling something from the demon world"},{"name":"Forbidden Charm","desc":"rewriting what someone wants"},{"name":"Pacting","desc":"a pact with anything other than a spirit"},{"name":"Wearing","desc":"binding a spirit into a living person"},{"name":"Blood","desc":"ritual magic worked through blood"}]}};
