  if (Array.isArray(v)) return v.reduce((a, x) => a + ind + 2 + (x && typeof x === 'object' ? 1 + ylen(x, ind + 2) : String(x).length + 1), 0) || 3;
  if (v && typeof v === 'object') return Object.entries(v).reduce((a, [k, x]) => a + ind + k.length + 2 + (x && typeof x === 'object' ? 1 + ylen(x, ind + 2) : String(x).length + 1), 0) || 3;
