async function commitSetting(ops, head) {
  if (view.busy) return;
  const st = latestState(); if (!st) return;
  view.busy = true; render();
  try {
    const text = `${head}\n<UpdateVariable>\n<Analysis>Player setting (player tool). Not part of the story.</Analysis>\n<JSONPatch>\n${JSON.stringify(ops)}\n</JSONPatch>\n</UpdateVariable>\n\n${PH}`;
    await waitGlobalInitialized('Mvu');
    const next = await Mvu.parseMessage(text, _.cloneDeep(st.data));
    if (!next || !next.stat_data) throw new Error('MVU did not apply the setting.');
    await createChatMessages([{ role: 'user', message: text, is_hidden: true }], { refresh: 'none' });
    const id = getLastMessageId();
    await Mvu.replaceMvuData(next, { type: 'message', message_id: id });
    await setChatMessages([{ message_id: id }], { refresh: 'affected' });
    toastr.success('Setting saved.', 'Eldrasil');
    await eventEmit('eldrasil:state');
  } catch (err) {
    console.error('[Eldrasil UI]', err);
    toastr.error(String(err && err.message || err), 'Eldrasil');
  } finally { view.busy = false; render(); }
}

// 1.1.0 weather glyph for the UI (the bracelet uses Font Awesome icons)
const wxIcon = wx => { const n = wx && wx.now; if (!n) return ''; return n.rare === 'lightning storm' || n.sky === 'Storm' ? '⛈' : n.snow ? '❄' : n.sky === 'Rain' ? '🌧' : n.sky === 'Fog' ? '🌫' : n.sky === 'Overcast' ? '☁' : n.sky === 'Cloudy' ? '⛅' : wx.block === 2 ? '☾' : '☀'; };
const SEASON_OF = m => ['Winter', 'Winter', 'Spring', 'Spring', 'Spring', 'Summer', 'Summer', 'Summer', 'Autumn', 'Autumn', 'Autumn', 'Winter'][((num(m, 1) - 1) % 12 + 12) % 12];

// ---------------------------------------------------------------- shared helpers for Batch 4 panels
const imgURL = path => (DATA.assets && DATA.assets.base ? DATA.assets.base : '') + path;
const npcOf = id => DATA.npcs && DATA.npcs[id];
// D14: the name unlocks at Rank 1, or earlier once the story itself has named them ($ui.names, recorded by the engine)
// ...or when a connection you have learned names them (the note itself says who they are)
const _edgeNames = new WeakMap();
function namedByEdges(S) {
  if (!S || typeof S !== 'object') return new Set();
  if (!_edgeNames.has(S)) _edgeNames.set(S, new Set((DATA.rel || []).filter(e => edgeVisible(e, S) && ((S.Bonds || {})[e[0]])).map(e => e[1])));
  return _edgeNames.get(S);
}
const knowsName = (id, S) => { const b = ((S && S.Bonds) || {})[id]; return !!((b && b.Rank >= 1) || ((S && S.$ui && S.$ui.names) || []).includes(id) || namedByEdges(S).has(id)); };
const nameOf = (id, S, full) => { const n = npcOf(id); if (!n) return id; return knowsName(id, S) ? (full ? n.n : id) : (n.r || n.d); };
const initials = s => String(s).split(/\s+/).map(w => w[0]).join('').slice(0, 2).toUpperCase();
function avatar(id, S, cls = 'av') {
  const n = npcOf(id), label = n ? (knowsName(id, S) ? (/\bxs\b/.test(cls) ? id.slice(0, 2) : id) : '?') : initials(id);
  const ring = n ? n.dc : '#6f737b';
  return n ? `<img class="${cls}" style="border-color:${ring}" src="${esc(imgURL(n.t))}" alt="" data-fb="${esc(label)}" data-fbclass="${cls} fb">` : `<span class="${cls} fb" style="border-color:${ring}">${esc(label)}</span>`;
}
const TOPIC = l => { l = l.toLowerCase(); return /magic/.test(l) ? 'magic' : /pact/.test(l) ? 'pact' : /goal/.test(l) ? 'goal' : /backstory|history|family|home/.test(l) ? 'backstory' : /relation/.test(l) ? 'relationship' : 'other'; };
// v1.0.3 (F13): the AI's Secrets_revealed list is capped; $ui.secrets is the engine's permanent ledger. Unlocks read both.
const secretsOf = S => [...new Set([...((S && S.Campus_State && S.Campus_State.Secrets_revealed) || []), ...((S && S.$ui && S.$ui.secrets) || [])])];
// v1.0.3 (F02): Campus_State.NPC_status by NPC id (the engine keys it by first name; full names / other case still match)
const npcStatus = S => { const st = ((S && S.Campus_State) || {}).NPC_status || {}, ks = Object.keys(st);
  return id => { const k = ks.find(x => x === id || x.toLowerCase() === String(id).toLowerCase() || x.toLowerCase().split(/\s+/)[0] === String(id).toLowerCase()); return k ? st[k] : ''; }; };
// v1.0.3: students who left campus after Graduation (Campus_State.Graduated); no longer regulars or club members
const graduated = S => new Set((((S && S.Campus_State) || {}).Graduated) || []);
// v1.0.3 incoming cohorts: an NPC is at Halvard from campaign year DATA.npcs[id].a (1 = from the start) until they graduate
const curYear = S => Math.max(1, num((((S || {}).World) || {}).Year, 1));
const arrived = (id, S) => { const n = npcOf(id); return !n || (n.a || 1) <= curYear(S); };
const atHalvard = (id, S) => arrived(id, S) && !graduated(S).has(id);
const yearNow = (id, S) => { const n = npcOf(id); return n && n.y ? n.y + curYear(S) - (n.a || 1) : 0; };
const revealed = (S, id) => secretsOf(S).filter(x => String(x).split('.')[0].toLowerCase() === id.toLowerCase()).map(x => String(x).split('.').slice(1).join('.').toLowerCase());
function fieldUnlocked(id, f, S) {   // f = [label, text, rank]
  if (f[2] >= 99) { const r = revealed(S, id); return r.includes(TOPIC(f[0])) || r.includes(f[0].toLowerCase()); }
  const b = ((S && S.Bonds) || {})[id];
  return f[2] <= (b ? b.Rank : 0);
}
function edgeVisible(e, S) {         // e = [from, to, type, types, visibility, notes]
  const v = e[4]; if (v === 'public') return true;
  const r = Number(v.split(':')[1]);
  if (r >= 99) return revealed(S, e[0]).includes('relationship');
  const b = ((S && S.Bonds) || {})[e[0]];
  return !!(b && b.Rank >= r);
}
// ================================================================ 4.1 dossier · 4.2 bonds · 4.3 connections
const EDGE = {
  family: ['#c79a5a', 'Family'], romance: ['#e07aa0', 'Romance'], rival: ['#e0645a', 'Rivals'], fear: ['#9b7fd1', 'Fear'],
  dislike: ['#d07a4f', 'Dislike'], mentor: ['#5b8fd4', 'Mentor'], respect: ['#3f9f69', 'Respect'], friend: ['#7fc2a8', 'Friends'],
  knows: ['#7a7f88', 'Acquainted'], story: ['#e8d3a8', 'From the story'],
};
view.ptab = 'bonds'; view.gtypes = new Set(Object.keys(EDGE).filter(k => k !== 'knows'));
const YEARW = { 1: 'First-year', 2: 'Second-year', 3: 'Third-year' };
const pips = (p, n = 10) => `<span class="pips" aria-label="${fmt(p)} of ${n}">${_.range(n).map(i => `<i class="${i < Math.floor(p) ? 'on' : ''}"></i>`).join('')}</span>`;
const mini = (v, color) => `<span class="mini"><i style="width:${_.clamp(num(v), 0, 100)}%;background:${color}"></i></span>`;
function whoLine(id, S) {
  const n = npcOf(id); if (!n) return '';
  // 1.0.3: the school year moves with the campaign year; graduates are former students
  const y = S ? Math.min(3, yearNow(id, S)) : n.y;
  const g = n.g.startsWith('Year') ? (S && graduated(S).has(id) ? `Former student, ${n.dm} Dormitory` : `${YEARW[y] || 'Student'}, ${n.dm} Dormitory`) : n.g === 'Staff' ? 'Halvard staff' : n.g;
  return g;
}

PANELS.people = {
  live: true,
  render(S) {
    const tabs = [['bonds', 'Bonds'], ['graph', 'Connections']];
    const body = view.ptab === 'graph' ? peopleGraphHTML(S) : peopleListHTML(S);
    return `<div class="dlg" tabindex="-1"><div class="hd"><h2>People</h2>${view.stack.length ? '<button class="btn sm" data-act="back">Back</button>' : ''}<button class="x" data-act="close" aria-label="Close">×</button></div>
      <nav class="nav">${tabs.map(([id, l]) => `<button data-ptab="${id}" class="${view.ptab === id ? 'on' : ''}">${l}</button>`).join('')}</nav><div class="bd">${body}</div></div>`;
  },
  click(b, S) {
    if (b.dataset.ptab) { view.ptab = b.dataset.ptab; render(); return; }
    if (b.dataset.gtype) { const t = b.dataset.gtype; view.gtypes.has(t) ? view.gtypes.delete(t) : view.gtypes.add(t); render(); }
  },
  after(S) { if (view.ptab === 'graph') drawGraph(S); },
};

function peopleListHTML(S) {
  const B = S.Bonds || {}, here = Object.keys((S.Scene || {}).Present || {});
  const ids = Object.keys(B).sort((a, b) => (here.includes(b) - here.includes(a)) || (B[b].Rank - B[a].Rank) || (B[b].Progress - B[a].Progress));
  if (!ids.length) return '<div class="empty">You have not met anyone yet.</div>';
  return `<p class="lead">${ids.length} ${ids.length === 1 ? 'person' : 'people'} you have met. Bonds deepen through scenes; at a full bar the next rank needs a milestone scene.</p>` + ids.map(id => {
    const b = B[id], n = npcOf(id);
    const badges = [here.includes(id) ? '<span class="pill g">here now</span>' : '', b._Event_ready ? '<span class="pill w">bond event ready</span>' : '', b.Romance ? '<span class="pill r">romance</span>' : ''].join('');
    return `<button class="pr" data-open="npc:${esc(id)}">${avatar(id, S, 'av lg')}<span class="pm">
      <span class="pn">${esc(nameOf(id, S, true))}</span><span class="sub">${esc(b.Title || (n ? n.r || whoLine(id, S) : ''))}</span>
      <span class="pb"><span class="rk">Rank ${b.Rank}</span>${pips(b.Progress)}<span class="sub">Trust</span>${mini(b.Trust, '#3f9f69')}<span class="sub">Tension</span>${mini(b.Tension, '#e0645a')}</span>
      <span>${badges}</span></span></button>`;
  }).join('');
}

// ---------------------------------------------------------------- dossier
PANELS.npc = {
  live: true,
  render(S) {
    const id = view.arg, n = npcOf(id), b = (S.Bonds || {})[id], rank = b ? b.Rank : 0;
    const title = n ? nameOf(id, S, true) : id;
    const port = n ? `<img class="por" src="${esc(imgURL(n.p))}" alt="" style="object-position:${n.fc[0]}% ${n.fc[1]}%" data-fb="${esc(knowsName(id, S) ? initials(n.n) : '?')}" data-fbclass="por fb">` : `<span class="por fb">${esc(initials(id))}</span>`;
    let h = `<div class="dos">${port}<div><p class="name">${esc(title)}</p><div class="sub" style="margin:2px 0 8px">${esc([n && knowsName(id, S) && n.r, whoLine(id, S), graduated(S).has(id) && 'Graduated; has left campus'].filter(Boolean).join('. '))}</div>`;
    if (b) {
      h += `<div class="bond"><div class="l"><span class="rk">Rank ${b.Rank}</span>${pips(b.Progress)}<span class="sub">${fmt(b.Progress)}/10</span></div>
        ${b.Title ? `<div style="margin:4px 0">${esc(b.Title)}${b.Romance ? ' <span class="pill r">romance</span>' : ''}</div>` : ''}
        <div class="tt"><span class="sub">Trust ${b.Trust}</span>${mini(b.Trust, '#3f9f69')}<span class="sub">Tension ${b.Tension}</span>${mini(b.Tension, '#e0645a')}</div>
        ${b._Event_ready ? `<div class="warn">The bond is ready for a milestone scene. Rank ${b.Rank + 1} comes from a meaningful moment with ${esc(knowsName(id, S) ? id : 'them')}, not from asking.</div>` : ''}
        ${b.Last_seen ? `<div class="sub">Last seen ${esc(b.Last_seen)}</div>` : ''}</div>`;
    } else h += '<div class="sub">You have not met yet.</div>';
    h += '</div></div>';
    if (n) {
      const open = n.fl.filter(f => fieldUnlocked(id, f, S) && !(/^(full )?name$/i.test(f[0]) && !knowsName(id, S)));
      h += open.map(f => `<h3>${esc(f[0])}${f[2] >= 99 ? ' <span class="pill f">uncovered</span>' : ''}</h3><p class="fv">${esc(f[1])}</p>`).join('');
      const locked = _.groupBy(n.fl.filter(f => f[2] < 99 && !fieldUnlocked(id, f, S)), f => f[2]);
      const lk = Object.keys(locked).sort((a, c) => a - c);
      if (lk.length) h += `<h3>Still to learn</h3>${lk.map(r => `<div class="lock">Rank ${r}: ${esc(_.uniq(locked[r].map(f => f[0])).join(', '))}</div>`).join('')}`;
      const views = DATA.rel.filter(e => e[0] === id && e[4] !== 'public' && arrived(e[1], S) && edgeVisible(e, S));
      if (views.length) h += `<h3>How they see others</h3>${views.map(e => `<div class="vw"><button class="lnk" data-open="npc:${esc(e[1])}">${esc(nameOf(e[1], S))}</button> <span class="pill" style="border-color:${EDGE[e[2]][0]};color:${EDGE[e[2]][0]}">${EDGE[e[2]][1]}</span><div class="sub">${esc(e[5][0])}</div></div>`).join('')}`;
    }
    const sec = revealed(S, id);
    if (sec.length) h += `<h3>Secrets uncovered</h3><div>${sec.map(t => `<span class="pill f">${esc(t)}</span>`).join('')}</div>`;
    const facts = b ? [...(b.$Known_old || []), ...(b.Known_facts || [])] : [];   // 5.4: older facts are kept in $Known_old
    if (facts.length) h += `<h3>What you know</h3><ul class="log">${facts.map(f => `<li>${esc(f)}</li>`).join('')}</ul>`;
    if (b && b.Milestones.length) h += `<h3>Milestones</h3><ul class="log">${b.Milestones.map(f => `<li>${esc(f)}</li>`).join('')}</ul>`;
    const st = ((S.Campus_State || {}).NPC_status || {});
    const stKey = Object.keys(st).find(k => k.toLowerCase() === id.toLowerCase());
    if (stKey) h += `<div class="warn">Now: ${esc(st[stKey])}</div>`;
    return `<div class="dlg" tabindex="-1" style="--dc:${n ? n.dc : '#9aa3ad'}"><div class="hd"><h2>Dossier</h2>${view.stack.length ? '<button class="btn sm" data-act="back">Back</button>' : ''}<button class="x" data-act="close" aria-label="Close">×</button></div><div class="bd">${h}</div></div>`;
  },
  click() {},
};

// ---------------------------------------------------------------- connections graph (D3, loaded on demand)
function graphModel(S) {
  const B = S.Bonds || {}, met = Object.keys(B);
  const links = new Map();
  const add = (a, c, type, note, src) => {
    const k = [a, c].sort().join('|');
    const L = links.get(k) || { source: a, target: c, types: new Set(), notes: [] };
    L.types.add(type); if (note && L.notes.length < 4) L.notes.push({ src, note }); links.set(k, L);
  };
  for (const e of DATA.rel) if (met.includes(e[0]) && arrived(e[1], S) && edgeVisible(e, S)) for (const t of e[3]) if (view.gtypes.has(t)) add(e[0], e[1], t, e[5][0], e[0]);   // 1.0.3: no incoming students yet
  if (view.gtypes.has('story')) for (const [k, v] of Object.entries((S.Campus_State || {}).New_relations || {})) {
    const [a, c] = k.split(/\s*(?:→|->)\s*/).map(x => (x || '').trim());
    const ida = Object.keys(DATA.npcs).find(i => i.toLowerCase() === (a || '').toLowerCase().split(' ')[0]) || a;
    const idc = Object.keys(DATA.npcs).find(i => i.toLowerCase() === (c || '').toLowerCase().split(' ')[0]) || c;
    if (ida && idc) add(ida, idc, 'story', v, 'story');
  }
  const ids = new Set(met);
  for (const L of links.values()) { ids.add(L.source); ids.add(L.target); }
  const nodes = [{ id: '__you', you: true }, ...[...ids].map(id => ({ id, met: met.includes(id) }))];
  const out = [...links.values()].map(L => ({ ...L, types: [...L.types], type: [...L.types].sort((x, y) => Object.keys(EDGE).indexOf(x) - Object.keys(EDGE).indexOf(y))[0] }));
  for (const id of met) out.push({ source: '__you', target: id, type: 'bond', rank: B[id].Rank, trust: B[id].Trust, tension: B[id].Tension, notes: [] });
  return { nodes, links: out };
}
function peopleGraphHTML(S) {
  const present = new Set();
  for (const e of DATA.rel) if (Object.keys(S.Bonds || {}).includes(e[0]) && edgeVisible(e, S)) e[3].forEach(t => present.add(t));
  if (Object.keys((S.Campus_State || {}).New_relations || {}).length) present.add('story');
  const chips = Object.entries(EDGE).filter(([k]) => present.has(k)).map(([k, [c, l]]) => `<button data-gtype="${k}" class="${view.gtypes.has(k) ? 'on' : ''}" style="--c:${c}" aria-pressed="${view.gtypes.has(k)}">${l}</button>`).join('');
  return `<p class="lead">Who you know, and what you have learned about how they relate to each other. Their views on others open up at bond Rank 5–6; family and teachers are common knowledge.</p>
    ${chips ? `<div class="tog gt">${chips}</div>` : '<div class="empty">No connections learned yet. Deepen a bond to Rank 5 to learn how someone sees the people around them.</div>'}
    <div class="graph"><svg class="g" role="img" aria-label="Connections diagram"></svg><div class="gload">Loading the diagram…</div></div>
    <div class="ginfo sub">Tap a line to read what you know about it; tap a person to open their dossier. Drag to rearrange, pinch or scroll to zoom.</div>`;
}
async function loadD3() {
  if (window.d3) return window.d3;
  if (!loadD3.p) loadD3.p = import('https://cdn.jsdelivr.net/npm/d3@7.9.0/+esm');
  return loadD3.p;
}
async function drawGraph(S) {
  const svgEl = ov.querySelector('svg.g'); if (!svgEl) return;
  let d3;
  try { d3 = await loadD3(); } catch (e) { const l = ov.querySelector('.gload'); if (l) l.textContent = 'The diagram library could not be loaded (needs internet).'; return; }
  if (!svgEl.isConnected) return;
  const ld = ov.querySelector('.gload'); if (ld) ld.remove();
  const W = svgEl.clientWidth || 600, H = svgEl.clientHeight || 450;
  const { nodes, links } = graphModel(S);
  const svg = d3.select(svgEl).attr('viewBox', [-W / 2, -H / 2, W, H]);
  const g = svg.append('g');
  svg.call(d3.zoom().scaleExtent([0.4, 3]).on('zoom', ev => g.attr('transform', ev.transform)));
  const info = ov.querySelector('.ginfo');
  const lk = g.append('g').selectAll('line').data(links).join('line')
    .attr('stroke', d => d.type === 'bond' ? '#b39062' : EDGE[d.type][0])
    .attr('stroke-width', d => d.type === 'bond' ? 1.5 + d.rank * 0.45 : 2.2)
    .attr('stroke-dasharray', d => d.type === 'knows' ? '4 4' : null)
    .attr('stroke-opacity', d => d.type === 'bond' ? 0.55 : 0.85).style('cursor', 'pointer')
    .on('click', (ev, d) => {
      if (!info) return;
      const a = d.source.id || d.source, c = d.target.id || d.target;
      if (d.type === 'bond') { info.innerHTML = `<b>You and ${esc(nameOf(c, S))}</b>: Rank ${d.rank}, trust ${d.trust}, tension ${d.tension}.`; return; }
      info.innerHTML = `<b>${esc(nameOf(a, S))} and ${esc(nameOf(c, S))}</b>: ${d.types.map(t => EDGE[t][1].toLowerCase()).join(', ')}` +
        d.notes.map(x => `<div style="margin-top:4px">${x.src === 'story' ? '' : `<span class="sub">${esc(nameOf(x.src, S))}'s side:</span> `}${esc(x.note)}</div>`).join('');
    });
  const nd = g.append('g').selectAll('g').data(nodes).join('g').style('cursor', 'pointer');
  nd.append('circle').attr('r', d => d.you ? 20 : 17).attr('fill', '#1d2126')
    .attr('stroke', d => d.you ? '#b9eadf' : (npcOf(d.id) ? npcOf(d.id).dc : '#6f737b')).attr('stroke-width', d => d.met || d.you ? 2.5 : 1.5)
    .attr('stroke-dasharray', d => d.met || d.you ? null : '3 2');
  nd.append('text').attr('text-anchor', 'middle').attr('dy', '0.35em').attr('fill', '#cfcbc2').attr('font-size', 11)
    .text(d => d.you ? 'You' : initials(knowsName(d.id, S) ? (npcOf(d.id) || { n: d.id }).n : '?'));
  nd.filter(d => !d.you && npcOf(d.id)).append('image').attr('href', d => imgURL(npcOf(d.id).t)).attr('x', -15).attr('y', -15).attr('width', 30).attr('height', 30)
    .style('clip-path', 'circle(50%)').on('error', function () { this.remove(); });
  nd.append('text').attr('text-anchor', 'middle').attr('y', 32).attr('fill', '#e6e3dc').attr('font-size', 12)
    .attr('paint-order', 'stroke').attr('stroke', '#1d2126').attr('stroke-width', 3)
    .text(d => d.you ? (S.Player.Profile.Name || '') : knowsName(d.id, S) ? d.id : (npcOf(d.id) ? '?' : d.id));
  nd.append('title').text(d => d.you ? 'You' : nameOf(d.id, S, true));
  nd.on('click', (ev, d) => { if (!d.you && !ev.defaultPrevented) open('npc:' + d.id); });
  const sim = d3.forceSimulation(nodes)
    .force('link', d3.forceLink(links).id(d => d.id).distance(d => d.type === 'bond' ? 120 - d.rank * 5 : 80))
    .force('charge', d3.forceManyBody().strength(-260)).force('collide', d3.forceCollide(30)).force('x', d3.forceX()).force('y', d3.forceY());
  const you = nodes[0]; you.fx = 0; you.fy = 0;
  nd.call(d3.drag().on('start', (ev, d) => { if (!ev.active) sim.alphaTarget(0.2).restart(); d.fx = d.x; d.fy = d.y; })
    .on('drag', (ev, d) => { d.fx = ev.x; d.fy = ev.y; }).on('end', (ev, d) => { if (!ev.active) sim.alphaTarget(0); if (!d.you) { d.fx = null; d.fy = null; } }));
  sim.on('tick', () => {
    lk.attr('x1', d => d.source.x).attr('y1', d => d.source.y).attr('x2', d => d.target.x).attr('y2', d => d.target.y);
    nd.attr('transform', d => `translate(${d.x},${d.y})`);
  });
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) { sim.stop(); for (let i = 0; i < 300; i++) sim.tick(); sim.on('tick')(); }
}

// ================================================================ 4.4 interactive map (D5–D8, D21)
view.pin = null; view.floor = ''; view.focusLoc = '';
const CARD_W = 280, CROP_H = 96, CROP_SCALE = 4;
const normPlace = s => String(s || '').split(/\s+[—-]\s+/)[0].trim().toLowerCase().replace(/^the\s+/, '');
const PLACE_ALIAS = { 'main courtyard': 'courtyards', 'courtyard': 'courtyards', 'gatehouse': 'reception_and_gatehouse', 'reception': 'reception_and_gatehouse' };
function locIdOf(place) {
  const p = normPlace(place); if (!p) return '';
  if (PLACE_ALIAS[p] && DATA.locs[PLACE_ALIAS[p]]) return PLACE_ALIAS[p];
  return Object.keys(DATA.locs).find(id => normPlace(DATA.locs[id].name) === p) || Object.keys(DATA.locs).find(id => id.replace(/_/g, ' ') === p) || '';
}
const discovered = (S, l) => !l.discoverable || ((S.$ui || {}).discovered || []).some(d => normPlace(d) === normPlace(l.name));
const pinOf = id => DATA.pins.find(p => p.cluster.includes(id) && p.pin === (DATA.locs[id] || {}).pin) || DATA.pins.find(p => p.cluster.includes(id));
function cropStyle(pin) {
  const Iw = CARD_W * CROP_SCALE, Ih = Iw * DATA.assets.size[1] / DATA.assets.size[0];
  const x = _.clamp(CARD_W / 2 - pin.x / 100 * Iw, CARD_W - Iw, 0), y = _.clamp(CROP_H / 2 - pin.y / 100 * Ih, CROP_H - Ih, 0);
  return `background-image:url('${esc(imgURL(DATA.assets.map))}');background-size:${Iw}px ${Math.round(Ih)}px;background-position:${Math.round(x)}px ${Math.round(y)}px`;
}
const goText = name => `I head to the ${String(name).replace(/^the\s+/i, '')}.`;

PANELS.map = {
  live: true,
  render(S) {
    const cur = locIdOf(S.World.Location), curPin = cur ? pinOf(cur) : null;
    if (view.pin == null && curPin) view.pin = curPin.pin;
    const pins = DATA.pins.filter(p => p.cluster.some(id => DATA.locs[id] && discovered(S, DATA.locs[id])));
    const pinHTML = pins.map(p => {
      const here = curPin && curPin.pin === p.pin, sel = view.pin === p.pin;
      return `<button class="pin${here ? ' here' : ''}${sel ? ' sel' : ''}" data-pin="${p.pin}" style="left:${p.x}%;top:${p.y}%" aria-label="${esc(p.label)}${here ? ' (you are here)' : ''}" title="${esc(p.label)}"></button>`
        + (sel || here ? `<span class="plab${here ? ' here' : ''}" style="left:${p.x}%;top:${p.y}%">${esc(p.label)}</span>` : '');
    }).join('');
    let sheet = '<p class="hint">Tap a marker to see what is there.</p>';
    const P = DATA.pins.find(p => p.pin === view.pin);
    if (P) {
      let ids = P.cluster.filter(id => DATA.locs[id] && discovered(S, DATA.locs[id]));
      let tabs = '';
      if (P.tabs) {
        const floors = P.tabs.filter(f => ids.some(id => DATA.locs[id].floor === f));
        if (!floors.includes(view.floor)) view.floor = (cur && P.cluster.includes(cur) && DATA.locs[cur].floor) || floors[1] || floors[0];
        tabs = `<div class="tog fl">${floors.map(f => `<button data-floor="${esc(f)}" class="${view.floor === f ? 'on' : ''}">${esc(f)}</button>`).join('')}</div>`;
        ids = ids.filter(id => DATA.locs[id].floor === view.floor);
      }
      sheet = `<h3>${esc(P.label)}</h3>${tabs}<div class="car">${ids.map(id => locCard(id, S, cur, P)).join('')}</div>${ids.length > 1 ? '<div class="hint">Swipe for more places here.</div>' : ''}`;
    }
    return `<div class="dlg wide" tabindex="-1"><div class="hd"><h2>Halvard</h2>${view.stack.length ? '<button class="btn sm" data-act="back">Back</button>' : ''}<button class="x" data-act="close" aria-label="Close">×</button></div>
      <div class="bd"><div class="mapwrap"><div><div class="map"><img src="${esc(imgURL(DATA.assets.map))}" alt="Map of Halvard Academy" data-fb="" data-fbclass="mapfb">${pinHTML}</div>
      <div class="sub" style="margin:6px 0 10px">You are at ${esc(S.World.Location)}.</div></div><div class="sheet">${sheet}</div></div></div></div>`;
  },
  click(b, S) {
    if (b.dataset.pin) { view.pin = +b.dataset.pin; view.floor = ''; render(); return; }
    if (b.dataset.floor) { view.floor = b.dataset.floor; render(); return; }
    if (b.dataset.loc) { const p = pinOf(b.dataset.loc); if (p) { view.pin = p.pin; view.floor = DATA.locs[b.dataset.loc].floor || ''; view.focusLoc = b.dataset.loc; render(); } return; }
    if (b.dataset.go) fillChat(goText(DATA.locs[b.dataset.go].name));   // shared helper (30_notebook.js)
  },
  after() {
    if (!view.focusLoc) return;
    const c = ov.querySelector(`[data-card="${view.focusLoc}"]`); view.focusLoc = '';
    if (c) c.scrollIntoView({ block: 'nearest', inline: 'start' });
  },
};

function classHint(S) {
  const m = /^P([123]) /.exec((S.World || {})._Period || ''); if (!m || !featureOn(S, 'class')) return '';
  const i = +m[1] - 1, until = ['10:00', '12:00', '16:00'][i], cell = (CAL.TIMETABLE[S.World.Day] || [])[i] || '';
  return /^Study Hall/.test(cell) ? `Study Hall until ${until}` : /^Clubs/.test(cell) ? `at their club until ${until}` : `in class until ${until}`;
}
function locCard(id, S, cur, P) {
  const l = DATA.locs[id], here = id === cur;
  const change = Object.entries((S.Campus_State || {}).Location_changes || {}).filter(([k]) => normPlace(k) === normPlace(l.name)).map(([, v]) => v);
  const B = S.Bonds || {};
  const stOf = npcStatus(S);   // v1.0.3 (F02): Campus_State.NPC_status beats the lorebook's habits
  // 1.0.3: graduates and not-yet-arrived students are not regulars
  const busy = classHint(S);   // 1.1.0 (spec §1): students are in class / Study Hall / at their clubs during the periods
  const regs = l.regulars.filter(r => atHalvard(r, S)).map(r => (npcOf(r) ? (B[r] ? `<button class="lnk" data-open="npc:${esc(r)}">${esc(nameOf(r, S))}</button>` : esc(nameOf(r, S))) : esc(r))
    + (stOf(r) ? ` <span class="sub">(${esc(stOf(r))})</span>` : busy && /^Year/.test((npcOf(r) || {}).g || '') ? ` <span class="sub">(${busy})</span>` : '')).join(', ');
  const conns = l.connections.filter(c => DATA.locs[c] && discovered(S, DATA.locs[c])).map(c => `<button class="lnk" data-loc="${esc(c)}">${esc(DATA.locs[c].name)}</button>`).join(', ');
  const walk = l.walk_min == null ? '' : l.walk_min === 0 ? 'At the Main Courtyard' : l.walk_min < 5 ? 'Under 5 min from the Main Courtyard' : `About ${l.walk_min} min from the Main Courtyard`;
  const rows = [
    regs && ['Regulars', regs], conns && ['Connected to', conns], walk && ['Walk', esc(walk)],
    l.clubs.length && ['Clubs here', esc(l.clubs.join(', '))], l.access && ['Access', esc(l.access)],
  ].filter(Boolean);
  return `<article class="lc${here ? ' here' : ''}" data-card="${esc(id)}"><div class="crop" style="${cropStyle(P)}"><b>${esc(l.name)}</b>${here ? '<span class="you">You are here</span>' : ''}</div>
    <div class="in">${l.vibe ? `<p class="vibe">${esc(l.vibe)}</p>` : ''}
    <details><summary>Description</summary><p>${esc(l.description)}</p></details>
    <dl class="kv sm">${rows.map(([k, v]) => `<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl>
    ${l.lore.length ? `<details><summary>Lore and rumours (${l.lore.length})</summary>${l.lore.map(x => `<p><b>${esc(x.title)}</b>: ${esc(x.summary)}</p>`).join('')}</details>` : ''}
    ${change.length ? `<div class="warn">Changed: ${change.map(esc).join('; ')}</div>` : ''}
    <button class="btn ${here ? '' : 'pri'} go" data-go="${esc(id)}" ${here ? 'disabled' : ''}>${here ? 'You are here' : 'Go here'}</button></div></article>`;
}

// ================================================================ 5.1 Notebook: Planner (F14), Notice Board (F15), Letters (F16), Journal + Mystery Board (F17)
// Calendar + timetable come from the engine template (single source), injected by tools/gen_ui.py.
const CAL = (() => {
const ALL = DAYS, MON_THU = DAYS.slice(0, 4), MON_FRI = DAYS.slice(0, 5), MON_SAT = DAYS.slice(0, 6);
const EVENTS = [
  { m: 1, w: 1, d: ['Mon'], t: 'Entrance Event (Arbiter Stone sorting)', noclass: 1 },
  { m: 1, w: 3, d: ['Sat', 'Sun'], t: 'Star Night (Sat evening to Sun dawn; no 8pm curfew)', nocurfew: 1 },
  { m: 1, w: 4, d: ['Sat'], t: 'Spiritual Dorm Day' },
  { m: 2, w: 1, d: ['Fri', 'Sat'], t: 'Warding Rite (Fri dusk to Sat dawn; the whole academy renews the wards)' },
  { m: 2, w: 3, d: ['Wed', 'Thu', 'Fri'], t: 'Creature Studies Expedition (off-grounds, Grade III country)', noclass: 1, away: 1 },
  { m: 3, w: 1, d: MON_THU, t: 'Midterm exams', noclass: 1 },
  { m: 3, w: 2, d: ['Fri', 'Sat'], t: 'Club Festival' },
  { m: 3, w: 3, d: MON_SAT, t: 'Training Week (cross-dorm sparring allowed; curfew 21:00)', curfew: 21 },
  { m: 3, w: 4, d: ['Sat', 'Sun'], t: 'Dorm Competition (solo, top 16 qualify)', noclass: 1 },
  { m: 4, w: 1, d: ['Wed'], t: 'Secret Fools Day (prank day, dorm name-draw)' },
  { m: 4, w: 2, d: ['Tue'], t: 'Independence Crowning Day (airship trip to the capital; fireworks on campus at night; curfew 22:00)', noclass: 1, curfew: 22, away: 1 },
  { m: 4, w: 3, d: ['Sat'], t: 'Mystic Dorm Day' },
  { m: 5, w: 1, d: MON_THU, t: 'End of Semester exams', noclass: 1 },
  { m: 5, w: 2, d: ['Fri'], t: 'Results & Dorm Ranking (Player.Profile.Dorm_rank is updated today)', ranking: 1 },
  { m: 5, w: 4, d: ALL, t: 'Mid-Year Break (students go home)', home: 1 },
  { m: 6, w: 1, d: MON_FRI, t: 'Return Week' },
  { m: 6, w: 3, d: ['Sat'], t: 'Sports Day (magic banned outright)' },
  { m: 6, w: 4, d: ['Wed', 'Thu', 'Fri', 'Sat'], t: 'Academy Competition (cross-dorm teams of 4)' },
  { m: 7, w: 2, d: ALL, t: 'Magical & Science Fair week' },
  { m: 7, w: 3, d: ALL, t: 'The Thinning: the seal is at its weakest; academy locked down all week', lockdown: 1 },
  { m: 8, w: 2, d: ['Thu', 'Fri', 'Sat', 'Sun'], t: 'Traveling Circus visits (Thu evening to Sun)' },
  { m: 8, w: 3, d: ['Thu', 'Fri', 'Sat'], t: 'Academy Showcase' },
  { m: 8, w: 4, d: ['Sat'], t: 'Elemental Dorm Day' },
  { m: 9, w: 1, d: MON_THU, t: 'Midterm exams', noclass: 1 },
  { m: 9, w: 2, d: ['Thu', 'Fri', 'Sat'], t: 'Academy Bazaar' },
  { m: 9, w: 3, d: ['Sat'], t: 'Academy Founder Day' },
  { m: 9, w: 4, d: ['Thu', 'Fri', 'Sat', 'Sun'], t: 'Kingdom Competition (four academies, one team each)' },
  { m: 10, w: 1, d: ['Tue'], t: 'Remembrance Day' },
  { m: 10, w: 2, d: ['Sat'], t: 'Occult Dorm Day' },
  { m: 10, w: 4, d: ['Fri', 'Sat', 'Sun'], t: 'Harvest Festival (Fri evening to Sun)' },
  { m: 11, w: 1, d: MON_THU, t: 'End of Semester exams', noclass: 1 },
  { m: 11, w: 2, d: ['Fri'], t: 'Results & Final Ranking (Player.Profile.Dorm_rank is updated today)', ranking: 1 },
  { m: 11, w: 3, d: ['Mon', 'Tue', 'Wed'], t: 'Academy Trip (Sunreach Bay, abroad)', noclass: 1, away: 1 },
  { m: 11, w: 4, d: ['Wed', 'Thu', 'Fri', 'Sat'], t: 'World Competition abroad (the national four)', away: 1 },
  { m: 11, w: 4, d: ['Sun'], t: 'Graduation (everyone attends; third-years leave by airship next morning)', noclass: 1, grad: 1 },
  { m: 12, w: 1, d: ALL, t: 'Kingdom-wide holiday: students go home', home: 1 },
  { m: 12, w: 2, d: ALL, t: 'Kingdom-wide holiday: students go home', home: 1 },
  { m: 12, w: 3, d: ALL, t: 'Kingdom-wide holiday: students go home', home: 1 },
  { m: 12, w: 4, d: ALL, t: 'Kingdom-wide holiday: students go home', home: 1 },
];
const TIMETABLE = {
  Mon: ['Magic Theory [M]', 'History [M]', 'Combat [D] (Combat Grounds)'],
  Tue: ['Dark Magic Defense [D]', 'Magic Theory [D]', 'Potion Crafting [M] (Potion Halls)'],
  Wed: ['Etiquette [M]', 'Dark Magic Defense [M]', 'Creature Studies [M] (Menagerie or Forest)'],
  Thu: ['History [M]', 'Magic Theory [D]', 'Combat [D] (Combat Grounds)'],
  Fri: ['Magic Theory [M]', 'Etiquette [M]', 'Dark Magic Defense practical [D] (Doves; Combat Grounds or warded seminar room)'],
  Sat: ['Etiquette [M]', 'Study Hall (unsupervised, Main Library)', 'Clubs (club venues)'],
};
return { EVENTS, TIMETABLE };
})();
view.nb = 'planner'; view.calOff = 0; view.letter = { to: '', body: '' };
// [id, label, unlock, features (any on)] — 1.1.0: a tab whose features are all off is hidden (the board also carries the forecast)
const NB_TABS = [['planner', 'Planner'], ['journal', 'Journal'], ['notices', 'Notice Board', 'notices', ['notices', 'weather']], ['letters', 'Letters', 'letters', ['letters']], ['mystery', 'Mystery Board', 'mystery', ['mystery']]];
const dayIdx = (M, W, D) => (M - 1) * 28 + (W - 1) * 7 + Math.max(0, DAYS.indexOf(D));   // day of the year, 0-based
const dayOf = i => { i = ((i % 336) + 336) % 336; return { M: Math.floor(i / 28) + 1, W: Math.floor((i % 28) / 7) + 1, D: DAYS[i % 7] }; };
const eventsOnDay = (M, W, D) => CAL.EVENTS.filter(e => e.m === M && e.w === W && e.d.includes(D));
const shortEv = t => String(t).split(' (')[0].split(':')[0];
const relDay = n => n === 0 ? 'Today' : n === 1 ? 'Tomorrow' : n === -1 ? 'Yesterday' : n > 0 ? `In ${n} days` : `${-n} days ago`;
function fillChat(text) {          // D6/D3: the UI never moves the story itself; it drafts the action for the player to edit and send
  const ta = PD.querySelector('#send_textarea');
  if (!ta) { toastr.info(text, 'Copy this into the chat'); return; }
  $('#send_textarea').val(text).trigger('input');
  close(); ta.focus(); try { ta.setSelectionRange(text.length, text.length); } catch (e) { /* ignore */ }
}
function peopleIn(str, S) {        // "Irene and Etnie" / "Irene, Rei" -> avatars for known NPCs, plain text otherwise
  return String(str || '').split(/\s*(?:,|&|\band\b|\/)\s*/).filter(Boolean).map(x => {
    const id = Object.keys(DATA.npcs || {}).find(k => k.toLowerCase() === x.toLowerCase() || DATA.npcs[k].n.toLowerCase() === x.toLowerCase());
    return id ? `<button class="who" data-open="npc:${esc(id)}">${avatar(id, S, 'av xs')}<span>${esc(nameOf(id, S))}</span></button>` : `<span class="who"><span>${esc(x)}</span></span>`;
  }).join('');
}
const unlockedTab = (S, t) => (!t[2] || ((S.$ui || {}).unlocks || []).includes(t[2])) && (!t[3] || t[3].some(f => featureOn(S, f)));

PANELS.notebook = {
  get live() { return view.nb !== 'letters'; },   // keep a half-written letter from being wiped by a refresh
  render(S) {
    if (view.arg && NB_TABS.some(t => t[0] === view.arg)) { view.nb = view.arg; view.arg = ''; }
    const tabs = NB_TABS.filter(t => unlockedTab(S, t));
    if (!tabs.some(t => t[0] === view.nb)) view.nb = 'planner';
    const late = featureOn(S, 'planner') ? Object.values(S.Commitments || {}).filter(c => c._Late).length : 0;
    const mail = featureOn(S, 'letters') ? Object.values(S.Letters || {}).filter(l => l.Status === 'waiting').length : 0;
    const badge = id => (id === 'planner' && late ? `<i class="nbb bad">${late}</i>` : id === 'letters' && mail ? `<i class="nbb">${mail}</i>` : '');
    const body = ({ planner: nbPlanner, journal: nbJournal, notices: nbNotices, letters: nbLetters, mystery: nbMystery })[view.nb](S);
    return `<div class="dlg wide" tabindex="-1"><div class="hd"><h2>Notebook</h2>${view.stack.length ? '<button class="btn sm" data-act="back">Back</button>' : ''}<button class="x" data-act="close" aria-label="Close">×</button></div>
      <nav class="nav">${tabs.map(([id, l]) => `<button data-nb="${id}" class="${view.nb === id ? 'on' : ''}">${l}${badge(id)}</button>`).join('')}</nav><div class="bd">${body}</div></div>`;
  },
  input(el) { if (el.dataset.lt) view.letter[el.dataset.lt] = el.value; },
  click(b, S) {
    if (b.dataset.nb) { view.nb = b.dataset.nb; render(); ov.querySelector('.bd').scrollTop = 0; return; }
    if (b.dataset.cal) { view.calOff = _.clamp(view.calOff + +b.dataset.cal, 0, 11); render(); return; }
    if (b.dataset.go) { const l = DATA.locs[b.dataset.go]; if (l) fillChat(goText(l.name)); return; }
    if (b.dataset.fill) { fillChat(b.dataset.fill); return; }
    if (b.dataset.reply !== undefined) {
      view.letter.to = b.dataset.reply; render();
      const ta = ov.querySelector('[data-lt="body"]'); if (ta) { ta.scrollIntoView({ block: 'center' }); ta.focus(); } return;
    }
    if (b.dataset.act === 'sendletter') {
      const to = view.letter.to.trim(), body = view.letter.body.trim();
      if (!to) { toastr.warning('Who is the letter for?', 'Letters'); return; }
      const atTower = normPlace(S.World.Location) === 'mail tower';
      const text = `I write a letter to ${to}${atTower ? ' and hand it in on the sorting floor' : ', to send from the Mail Tower'}.${body ? ` It reads: "${body}"` : ''}`;
      view.letter = { to: '', body: '' }; fillChat(text);
    }
  },
};

// ---------------------------------------------------------------- planner
function hapCard(S) {               // 5.3 (F20): today's seeded happening; optional, the player decides whether to go
  const h = (S.$ui || {}).hap; if (!h || !h.text) return '';
  const lid = h.where ? locIdOf(h.where) : '';
  const here = lid && normPlace(S.World.Location) === normPlace(DATA.locs[lid].name);
  return `<div class="hap"><span class="pill${h.now ? ' w' : ''}">${h.now ? `now, until ${h.to}:00` : `${h.from}:00–${h.to}:00`}</span> <b>${esc(h.where || 'Around campus')}</b><div>${esc(h.text)}</div>
    ${lid && !here ? `<button class="btn sm" data-go="${esc(lid)}">Go here</button>` : ''}</div>`;
}
function nbPlanner(S) {
  const W = S.World, today = dayIdx(W.Month, W.Week, W.Day);
  const now = `<div class="now"><b>${esc(`${W.Day} ${W.Time}`)}</b> <span class="sub">Month ${W.Month}, Week ${W.Week}</span><div>${esc(W._Period || 'Free time')}</div>
    ${W._Weather && featureOn(S, 'weather') ? `<div class="sub">${esc(wxIcon((S.$ui || {}).wx))} ${esc(W._Weather)}</div>` : ''}
    ${W._Event_today ? `<div class="ev">${esc(W._Event_today)}</div>` : ''}${W._Curfew ? `<div class="cf">${esc(W._Curfew)}</div>` : ''}${featureOn(S, 'happenings') ? hapCard(S) : ''}</div>`;
  // commitments
  const C = Object.entries(S.Commitments || {}).sort(([, a], [, b]) => ((a.$abs < 0) - (b.$abs < 0)) || (a.$abs - b.$abs));
  const com = C.length ? C.map(([k, c]) => {
    const lid = c.Where ? locIdOf(c.Where) : '';
    const when = c._Late ? '<span class="pill f">overdue</span>' : c._When ? `<span class="pill${/^today/.test(c._When) ? ' w' : ''}">${esc(c._When)}</span>` : (c.Due ? `<span class="pill">${esc(c.Due)}</span>` : '');
    return `<div class="item cm${c._Late ? ' late' : ''}"><div class="row"><span class="t">${esc(k)}</span>${c.Type ? `<span class="pill">${esc(c.Type)}</span>` : ''}${when}</div>
      ${c.Desc ? `<div>${esc(c.Desc)}</div>` : ''}<div class="meta">${c.With ? peopleIn(c.With, S) : ''}${c.Where ? `<span class="sub">at ${esc(c.Where)}</span>` : ''}
      ${lid && normPlace(S.World.Location) !== normPlace(DATA.locs[lid].name) ? `<button class="btn sm" data-go="${esc(lid)}">Go here</button>` : ''}</div></div>`;
  }).join('') : '<div class="empty">Nothing promised, nothing due. Commitments appear here when you make them in the story.</div>';
  // this week's timetable
  const P = /^P(\d)/.exec(W._Period || ''), per = P ? +P[1] - 1 : -1;
  const rows = DAYS.map(D => {
    const evs = eventsOnDay(W.Month, W.Week, D), stop = evs.find(e => e.noclass || e.home || e.lockdown), tt = CAL.TIMETABLE[D];
    const isToday = D === W.Day;
    const cells = !tt ? `<td colspan="3" class="off">No classes</td>` : stop ? `<td colspan="3" class="off ev">${esc(shortEv(stop.t))}</td>`
      : tt.map((c, i) => `<td class="${isToday && i === per ? 'cur' : ''}">${esc(c.replace(/\s*\[(M|D)\]/, ''))}${/\[D\]/.test(c) ? ' <span class="dm" title="Taught to each dorm separately">dorm</span>' : ''}</td>`).join('');
    const extra = evs.filter(e => e !== stop).map(e => `<div class="sub ev">${esc(shortEv(e.t))}</div>`).join('');
    return `<tr class="${isToday ? 'today' : ''}"><th>${D}${extra}</th>${cells}</tr>`;
  }).join('');
  const table = `<div class="scroll"><table class="tt"><tr><th></th><th>08:00–10:00</th><th>10:00–12:00</th><th>13:00–16:00</th></tr>${rows}</table></div>`;
  // month calendar
  const mo = ((W.Month - 1 + view.calOff) % 12) + 1;
  const comByDay = {};
  for (const [k, c] of C) if (c.$abs >= 0) { const d = Math.floor(c.$abs / 1440) % 336; (comByDay[d] = comByDay[d] || []).push(k); }
  const grid = _.range(4).map(w => DAYS.map(D => {
    const di = dayIdx(mo, w + 1, D), evs = eventsOnDay(mo, w + 1, D), cm = comByDay[di] || [];
    const cls = [di === today && view.calOff === 0 ? 'today' : '', evs.length ? 'has' : '', view.calOff === 0 && di < today ? 'past' : ''].join(' ');
    return `<div class="cd ${cls}" title="${esc([...evs.map(e => e.t), ...cm.map(k => 'Due: ' + k)].join('\n'))}"><span class="dn">${D.slice(0, 2)}</span>${evs.slice(0, 2).map(e => `<span class="ce">${esc(shortEv(e.t))}</span>`).join('')}${cm.length ? `<span class="cc">● ${cm.length}</span>` : ''}</div>`;
  }).join('')).map((r, w) => `<div class="wk"><span class="wl">W${w + 1}</span>${r}</div>`).join('');
  // coming up (14 days)
  const up = [];
  for (let n = 0; n < 15; n++) { const d = dayOf(today + n); for (const e of eventsOnDay(d.M, d.W, d.D)) if (!up.some(u => u.e === e)) up.push({ n, d, e }); }
  const upH = up.length ? `<ul class="up">${up.map(u => `<li><span class="rd">${relDay(u.n)}</span><span class="sub">M${u.d.M} W${u.d.W} ${u.d.D}</span> ${esc(u.e.t)}</li>`).join('')}</ul>` : '<div class="empty">Nothing on the academy calendar in the next two weeks.</div>';
  return `${now}${featureOn(S, 'planner') ? `<h3>Commitments</h3>${com}` : ''}<h3>This week</h3>${table}<h3>Coming up</h3>${upH}
    <h3 class="calh">Calendar: Month ${mo}${view.calOff ? '' : ' (now)'}<span><button class="btn sm" data-cal="-1" ${view.calOff ? '' : 'disabled'} aria-label="Previous month">‹</button><button class="btn sm" data-cal="1" ${view.calOff >= 11 ? 'disabled' : ''} aria-label="Next month">›</button></span></h3><div class="cal">${grid}</div>`;
}

// ---------------------------------------------------------------- journal
function nbJournal(S) {
  const parse = (l, old) => { const m = /^\[M(\d+) W(\d) (\w{3})\]\s*(.*)$/.exec(l); return m ? { M: +m[1], W: +m[2], D: m[3], t: m[4], old } : { M: 0, t: l, old }; };
  // 5.3 (F21): archived lines (the narrator no longer reads them) stay in the player's journal, shown faded
  const J = [...((S.$ui || {}).archive || []).map(l => parse(l, true)), ...(S.Journal || []).map(l => parse(l, false))];
  const groups = _.groupBy([...J].reverse(), 'M');
  const months = [...new Set([...J].reverse().map(e => e.M))];
  const tl = J.length ? months.map(M => `<h4>${M ? `Month ${M}` : 'Undated'}</h4><ol class="jt">${groups[M].map(e => `<li${e.old ? ' class="old" title="Archived: the narrator no longer reads this line"' : ''}>${e.W ? `<span class="sub">W${e.W} ${e.D}</span>` : ''}${esc(e.t)}</li>`).join('')}</ol>`).join('') : '<div class="empty">Nothing written yet.</div>';
  const CS = S.Campus_State || {}, ev = Object.entries(CS.Events || {}), ru = [...(CS.Rumours || [])].reverse();
  // 1.1.0 (spec §3): how far each rumour has spread; rumours that died out stay, faded
  const gs = featureOn(S, 'gossip') ? Object.fromEntries(((S.$ui || {}).gossip || []).map(g => [g[0], g])) : {}, old = [...((S.$ui || {}).rumours_old || [])].reverse();
  return `<p class="lead">The turning points of your year, written as they happen. The narrator reads the latest 30 lines as the story's memory; older chat is trimmed from its context. Faded lines are archived: kept for you, no longer read by the narrator.</p>${tl}
    <h3>Campus news</h3>${ev.length ? `<dl class="kv">${ev.map(([k, v]) => `<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl>` : '<div class="empty">Nothing has changed on campus yet.</div>'}
    ${ru.length || old.length ? `<h3>Rumours</h3><ul class="log">${ru.map(r => `<li>${esc(r)}${gs[r] ? `<span class="reach">${esc(gs[r][1])} · day ${gs[r][2]}</span>` : ''}</li>`).join('')}${old.map(r => `<li class="old" title="Died out">${esc(r)}</li>`).join('')}</ul>` : ''}`;
}

// ---------------------------------------------------------------- notice board
function officialNotices(S) {
  const W = S.World, today = dayIdx(W.Month, W.Week, W.Day), out = [];
  for (let n = -1; n <= 10; n++) {
    const d = dayOf(today + n);
    for (const e of eventsOnDay(d.M, d.W, d.D)) {
      if (out.some(o => o.e === e) || e.home) continue;
      out.push({ e, n, d, t: e.ranking ? 'Results and dorm rankings' : shortEv(e.t), x: e.t.replace(/\s*\(Player\.Profile[^)]*\)/, '') });
    }
  }
  return out;
}
function nbNotices(S) {
  const off = officialNotices(S).map(o => `<div class="note off"><b>${esc(o.t)}</b><div>${esc(o.x)}</div><div class="sub">${esc(`${relDay(o.n)} · M${o.d.M} W${o.d.W} ${o.d.D}`)} · Academy Administration</div></div>`).join('');
  const N = featureOn(S, 'notices') ? Object.entries(S.Notices || {}).reverse() : [];
  const own = N.map(([k, v], i) => `<div class="note" style="--r:${[-1.2, .8, -.5, 1.1, -.9][i % 5]}deg"><b>${esc(k)}</b><div>${esc(v.Text)}</div>
    <div class="sub">${esc([v.By && `Posted by ${v.By}`, v.Posted, v.Until && `until ${v.Until}`].filter(Boolean).join(' · '))}</div>
    <button class="btn sm" data-fill="${esc(`About the notice "${k}" on the board: `)}">Act on it</button></div>`).join('');
  const fc = forecastCard(S);
  return `<p class="lead">The long wall of boards in the castle's Floor 1 entrance hall. Official postings go up ahead of every event; the rest is what students pin up, and it rarely stays long.</p>
    <h3>Official</h3>${off || fc ? `<div class="board">${fc}${off}</div>` : '<div class="empty">No official postings this fortnight.</div>'}
    ${featureOn(S, 'notices') ? `<h3>Pinned by students and staff</h3>${own ? `<div class="board">${own}</div>` : '<div class="empty">Nothing you have noticed yet. Paid work, club recruitment and lost items appear here once you have seen them.</div>'}` : ''}`;
}
// 1.1.0 (spec §4.7): the Divination Society posts tomorrow's skies at 07:00 (about 75% right; the bracelet and Planner do not show it)
function forecastCard(S) {
  const wx = (S.$ui || {}).wx; if (!featureOn(S, 'weather') || !wx || !wx.fc) return '';
  const B = ['Morning', 'Afternoon', 'Night'];
  return `<div class="note off fc"><b>Divination Society — ${wx.fc.tomorrow ? "tomorrow's" : "today's"} skies</b>
    <div class="fcb">${wx.fc.blocks.map((b, i) => `<span>${B[i]}</span><span>${esc(b.text)}, ${esc(b.label)}</span>`).join('')}</div>
    <div class="dis">The Society accepts no responsibility for umbrellas.</div><div class="sub">Posted ${wx.fc.tomorrow ? 'this morning' : 'yesterday'} at 07:00 · Divination Society</div></div>`;
}

// ---------------------------------------------------------------- letters
function nbLetters(S) {
  const L = Object.entries(S.Letters || {}).reverse();
  const atTower = normPlace(S.World.Location) === 'mail tower';
  const card = ([k, l]) => {
    const out = l.Status === 'sent', who = out ? l.To : l.From;
    const act = l.Status === 'waiting'
      ? `<button class="btn sm pri" data-fill="${esc(atTower ? `I collect the letter${l.From ? ` from ${l.From}` : ''} from my locker and read it.` : `I head to the Mail Tower to collect my letter${l.From ? ` from ${l.From}` : ''}.`)}">${atTower ? 'Collect and read' : 'Go and collect'}</button>`
      : l.Status === 'read' ? `<button class="btn sm" data-reply="${esc(l.From)}">Reply</button>` : '';
    const st = { waiting: '<span class="pill w">waiting at the Mail Tower</span>', read: '<span class="pill">read</span>', replied: '<span class="pill g">answered</span>', sent: '<span class="pill">sent</span>' }[l.Status];
    return `<div class="item letter ${l.Status}"><div class="row"><span class="t">${esc(k)}</span>${st}</div>
      <div class="meta"><span class="sub">${out ? 'To' : 'From'}</span>${peopleIn(who, S) || '<span class="sub">unknown</span>'}<span class="sub">${esc(l.Date)}</span></div>
      ${l.Status === 'waiting' ? '<div class="sub">Sealed. Collect it to learn what it says.</div>' : `<div class="gist">${esc(l.Gist)}</div>`}${act ? `<div style="margin-top:8px">${act}</div>` : ''}</div>`;
  };
  const inb = L.filter(([, l]) => l.Status !== 'sent'), sent = L.filter(([, l]) => l.Status === 'sent');
  const known = Object.keys(S.Bonds || {}).filter(id => knowsName(id, S)).map(id => (npcOf(id) || { n: id }).n);
  return `<p class="lead">Birds carry letters in and out of the Mail Tower; the sorting floor keeps them in numbered lockers until you collect them. A letter takes at least a day each way.</p>
    <h3>Received</h3>${inb.length ? inb.map(card).join('') : '<div class="empty">No letters yet.</div>'}
    ${sent.length ? `<h3>Sent</h3>${sent.map(card).join('')}` : ''}
    <h3>Write a letter</h3><div class="grid"><label class="f">To<input data-lt="to" list="eld-to" value="${esc(view.letter.to)}" placeholder="Someone at home, a friend…"></label>
    <datalist id="eld-to">${['My family', ...known].map(n => `<option value="${esc(n)}">`).join('')}</datalist><div></div>
    <label class="f full">What you want to say (optional)<textarea data-lt="body" placeholder="The narrator writes the letter out in the story.">${esc(view.letter.body)}</textarea></label></div>
    <div style="margin-top:10px"><button class="btn pri" data-act="sendletter">Draft it in the chat</button><div class="hint">This only fills in your message box. Edit it, then send it to play the scene.</div></div>`;
}

// ---------------------------------------------------------------- mystery board
function linkChip(x, S) {
  const id = Object.keys(DATA.npcs || {}).find(k => k.toLowerCase() === String(x).toLowerCase());
  if (id) return `<button class="who" data-open="npc:${esc(id)}">${avatar(id, S, 'av xs')}<span>${esc(nameOf(id, S))}</span></button>`;
  const lid = locIdOf(x);
  return `<span class="pill">${esc(lid ? DATA.locs[lid].name : x)}</span>`;
}
function nbMystery(S) {
  const Cl = Object.entries(S.Clues || {}), My = S.Mysteries || {};
  const order = { open: 0, cold: 1, solved: 2 };
  const threads = Object.keys(My).filter(t => Cl.some(([, c]) => c.Thread === t) || My[t].Summary).sort((a, b) => order[My[a].Status] - order[My[b].Status]);
  const board = threads.map(t => {
    const m = My[t], cs = Cl.filter(([, c]) => c.Thread === t);
    return `<section class="thread ${m.Status}"><div class="row"><span class="t">${esc(t)}</span><span class="pill ${m.Status === 'open' ? 'w' : m.Status === 'solved' ? 'g' : ''}">${m.Status}</span></div>
      <p class="sum">${esc(m.Summary || 'Nothing pieced together yet.')}</p><div class="clues">${cs.map(([k, c], i) => `<div class="clue" style="--r:${[-1, .7, -.4, 1][i % 4]}deg"><b>${esc(k)}</b><div>${esc(c.Detail)}</div>
      <div class="sub">${esc([c.Found, c.Where].filter(Boolean).join(' · '))}</div>${c.Links.length ? `<div class="meta">${c.Links.map(x => linkChip(x, S)).join('')}</div>` : ''}
      ${m.Status === 'open' ? `<button class="btn sm" data-fill="${esc(`I follow up on the clue "${k}": `)}">Follow up</button>` : ''}</div>`).join('')}</div></section>`;
  }).join('');
  const sec = _.groupBy(secretsOf(S), x => String(x).split('.')[0]);
  const truths = Object.entries(sec).map(([who, xs]) => {
    const id = Object.keys(DATA.npcs || {}).find(k => k.toLowerCase() === who.toLowerCase());
    const topics = xs.map(x => String(x).split('.').slice(1).join('.') || 'other');
    return `<div class="truth">${id ? linkChip(id, S) : `<span class="pill">${esc(who)}</span>`}<span>${topics.map(tp => `<span class="pill g">${esc(tp)}</span>`).join('')}</span></div>`;
  }).join('');
  return `<p class="lead">What you have noticed, and what it might mean. Clues are pinned by thread; solved threads move to the bottom.</p>
    ${board || '<div class="empty">No clues yet.</div>'}${truths ? `<h3>Truths uncovered</h3><p class="hint">Opens the matching part of each person's dossier.</p>${truths}` : ''}`;
}

// ================================================================ 5.2 Activities: Clubs, Competition, Shop, Projects, Trip (F18, F19) + Battle panel
view.act = 'clubs'; view.shop = 'All';
const ACT_TABS = [['clubs', 'Clubs'], ['competition', 'Competition', 'competition', ['competition']], ['shop', 'Shop'], ['projects', 'Projects', 'projects', ['projects']], ['trip', 'Trips', 'trip', ['trip']]];
const ROLES5 = ['Attack', 'Defense', 'Healing', 'Support', 'Control'];
const COMP_TIERS = [
  ['Dorm', 'Dorm Competition', 'Solo, open to the whole dorm, run as a ranking tournament so everyone finishes with a placement. The top 16 of each dorm qualify.'],
  ['Academy', 'Academy Competition', 'Qualifiers from all four dorms form teams of 4 with at least one student from each year, covering the combat roles between them. Knockout; the winning team represents Halvard.'],
  ['Kingdom', 'Kingdom Competition', 'One team per academy, four in all, knockout. Each member of the winning team earns 5,000 points.'],
  ['World', 'World Competition', 'Abroad. A panel picks the national four from the best individuals of the Kingdom Competition, winners and losers alike. Being picked off a losing team is a great honour.'],
];
const clubOf = S => { const c = String(((S.Player || {}).Profile || {}).Club || '').toLowerCase(); return c ? (DATA.clubs || []).find(x => c.includes(x.key.toLowerCase())) : null; };
const eventDay = rx => { const e = CAL.EVENTS.find(x => rx.test(x.t)); return e ? { e, di: dayIdx(e.m, e.w, e.d[0]) } : null; };
const daysTo = (S, di) => di - dayIdx(S.World.Month, S.World.Week, S.World.Day);
const whenLabel = n => n < 0 ? 'past' : relDay(n);
const clubFieldOpen = (id, S) => { const n = npcOf(id); const f = n && n.fl.find(x => x[0].toLowerCase() === 'club'); return !!(f && fieldUnlocked(id, f, S)); };
const hereIs = (S, lid) => !!lid && locIdOf(S.World.Location) === lid;
const aan = w => (/^[aeiou]/i.test(w) ? 'an ' : 'a ') + w;

PANELS.activities = {
  live: true,
  render(S) {
    if (view.arg && ACT_TABS.some(t => t[0] === view.arg)) { view.act = view.arg; view.arg = ''; }
    const tabs = ACT_TABS.filter(t => unlockedTab(S, t));
    if (!tabs.some(t => t[0] === view.act)) view.act = 'clubs';
    const body = ({ clubs: acClubs, competition: acCompetition, shop: acShop, projects: acProjects, trip: acTrip })[view.act](S);
    return `<div class="dlg wide" tabindex="-1"><div class="hd"><h2>Activities</h2>${view.stack.length ? '<button class="btn sm" data-act="back">Back</button>' : ''}<button class="x" data-act="close" aria-label="Close">×</button></div>
      <nav class="nav">${tabs.map(([id, l]) => `<button data-actab="${id}" class="${view.act === id ? 'on' : ''}">${l}</button>`).join('')}</nav><div class="bd">${body}</div></div>`;
  },
  click(b) {
    if (b.dataset.actab) { view.act = b.dataset.actab; render(); ov.querySelector('.bd').scrollTop = 0; return; }
    if (b.dataset.shop) { view.shop = b.dataset.shop; render(); return; }
    if (b.dataset.go) { const l = DATA.locs[b.dataset.go]; if (l) fillChat(goText(l.name)); return; }
    if (b.dataset.fill) fillChat(b.dataset.fill);
  },
};

// ---------------------------------------------------------------- clubs
function acClubs(S) {
  const mine = clubOf(S), P = S.Player.Profile, fest = eventDay(/^Club Festival/);
  const venueNames = c => c.venues.map(v => (DATA.locs[v] || { name: v }).name);
  const people = (c, withFollowers) => {
    // 1.0.3: graduates have left their clubs; incoming first-years are not members before they arrive
    const ids = [...c.advisors, ...c.members.filter(m => !c.advisors.includes(m)), ...(withFollowers ? c.follows || [] : [])].filter(id => atHalvard(id, S));
    const known = ids.filter(id => clubFieldOpen(id, S) || (withFollowers && (c.follows || []).includes(id)));
    const more = ids.length - known.length;
    return `${known.map(id => `<button class="who" data-open="npc:${esc(id)}">${avatar(id, S, 'av xs')}<span>${esc(nameOf(id, S))}${c.advisors.includes(id) ? ' (advisor)' : (c.follows || []).includes(id) ? ' (followed you in)' : ''}</span></button>`).join('')}${more > 0 ? `<span class="sub">+${more} you have not placed yet</span>` : ''}`;
  };
  const meets = c => `Meets Saturday 13:00–16:00${c.practice ? '; also practises informally after 16:00 on other days' : ''}.${c.sport ? ' Magic is banned during play.' : ''}`;
  let h = '';
  if (mine) {
    const v0 = mine.venues[0];
    h += `<div class="item mine"><div class="row"><span class="t">${esc(mine.name)}</span><span class="pill g">your club</span></div>
      <div class="sub">${esc(venueNames(mine).join(' · '))}</div><div>${esc(meets(mine))}</div><div class="meta">${people(mine, true)}</div>
      <div class="meta">${v0 && !hereIs(S, v0) ? `<button class="btn sm" data-go="${esc(v0)}">Go to the club</button>` : ''}
      <button class="btn sm" data-fill="${esc(`I spend the afternoon at the ${mine.name}: `)}">Club time</button></div></div>`;
  } else if (P.Club) h += `<div class="item mine"><div class="row"><span class="t">${esc(P.Club)}</span><span class="pill g">your club</span></div><div class="sub">A club not in the directory, founded or found in play.</div></div>`;
  else h += `<p class="lead">You have not joined a club. Clubs are the one place the four magic types mix freely, because recruitment happens before dorm loyalty settles.</p>`;
  if (fest) { const n = daysTo(S, fest.di); if (n >= -1 && n <= 21) h += `<div class="warn">Club Festival ${n < 0 ? 'was yesterday' : n === 0 ? 'is today' : `in ${n} days`} (M3 W2, Fri afternoon and Sat): every club runs a stand in the Main Courtyard; one gold coin each to vote for the best stand.</div>`; }
  h += `<h3>Directory</h3><div class="clubs">${(DATA.clubs || []).filter(c => c !== mine).map(c => `<div class="club"><b>${esc(c.name)}</b><div class="sub">${esc(venueNames(c).join(' · '))}${c.sport ? ' · sport, no magic in play' : ''}</div>
    <div class="meta">${people(c, false)}</div>
    <div class="meta">${!P.Club ? `<button class="btn sm" data-fill="${esc(`I go to the ${c.name} at ${venueNames(c)[0]} and ask about joining.`)}">Ask to join</button>` : ''}${c.venues[0] && !hereIs(S, c.venues[0]) ? `<button class="btn sm" data-go="${esc(c.venues[0])}">Go</button>` : ''}</div></div>`).join('')}</div>
    <h3>Found your own</h3><p class="hint">A new club needs a teaching staff signature and five members; one teacher is responsible for it. The Student Council allocates rooms, and a new club gets whatever is left.</p>
    <button class="btn sm" data-fill="I want to found a new club: ">Start a club in the story</button>`;
  return h;
}

// ---------------------------------------------------------------- competition
function acCompetition(S) {
  const Co = S.Competition || {}, P = S.Player.Profile;
  const dates = { Dorm: eventDay(/^Dorm Competition/), Academy: eventDay(/^Academy Competition/), Kingdom: eventDay(/^Kingdom Competition/), World: eventDay(/World Competition/) };
  const idx = COMP_TIERS.findIndex(t => t[0] === Co.Tier);
  const status = Co.Status ? `<div class="item"><div class="row"><span class="t">${esc(Co.Tier ? Co.Tier + ' Competition' : 'Competition')}</span><span class="pill ${Co.Status === 'eliminated' ? 'f' : /champion|selected|qualified/.test(Co.Status) ? 'g' : 'w'}">${esc(Co.Status)}</span></div>
    ${Co.Placement ? `<div>Placement: <b>${esc(Co.Placement)}</b></div>` : ''}${(Co.Results || []).length ? `<ul class="log">${Co.Results.map(r => `<li>${esc(r)}</li>`).join('')}</ul>` : ''}</div>`
    : `<p class="lead">You have not entered yet. Losing at any tier ends your competitive year; World selection is the one tier that is chosen, not won.</p>`;
  const ladder = COMP_TIERS.map(([k, name, desc], i) => {
    const d = dates[k], n = d ? daysTo(S, d.di) : null;
    const cls = i === idx ? (Co.Status === 'eliminated' ? 'out' : 'on') : i < idx ? 'done' : '';
    return `<li class="${cls}"><b>${esc(name)}</b>${d ? ` <span class="sub">M${d.e.m} W${d.e.w} ${d.e.d[0]}${n != null ? ` · ${whenLabel(n)}` : ''}</span>` : ''}<div class="sub">${esc(desc)}</div></li>`;
  }).join('');
  // team check (Academy tier and beyond): 4 members, every year level, the five roles covered
  let team = '';
  if (idx >= 1 || (Co.Team || []).length) {
    const mates = (Co.Team || []).slice(0, 3), stOf = npcStatus(S);
    // v1.0.3 (F02): a teammate with a status on record (graduated, injured, expelled…) is not counted until the story confirms them
    const gone = graduated(S), stOf2 = id => (gone.has(id) ? 'graduated, left campus' : stOf(id));
    const flagged = mates.filter(id => stOf2(id)), counted = mates.filter(id => !stOf2(id));
    const roles = new Set(ROLES5.filter(r => new RegExp(r, 'i').test(P.Combat_role || '')));
    counted.forEach(id => { const n = npcOf(id); if (n && n.tr) roles.add(n.tr); });
    const years = new Set([P.Year, ...counted.map(id => Math.min(3, yearNow(id, S))).filter(Boolean)]);   // 1.0.3: this year's level
    team = `<h3>Your team</h3><div class="meta"><span class="who"><span>You${P.Combat_role ? ` (${esc(P.Combat_role)})` : ''}</span></span>${mates.map(id => npcOf(id) ? `<button class="who" data-open="npc:${esc(id)}">${avatar(id, S, 'av xs')}<span>${esc(nameOf(id, S))}${npcOf(id).tr ? ` (${npcOf(id).tr})` : ''}</span></button>` : `<span class="who"><span>${esc(id)}</span></span>`).join('')}</div>
      <div class="meta">${ROLES5.map(r => `<span class="pill ${roles.has(r) ? 'g' : ''}">${roles.has(r) ? '✓' : '·'} ${r}</span>`).join('')}</div>
      <div class="hint">${mates.length + 1}/4 members · years covered: ${[1, 2, 3].map(y => years.has(y) ? `Y${y} ✓` : `Y${y} missing`).join(', ')}. Only your own roles and rival-team roles are on record; check your teammates' roles in the story.${flagged.length ? ` Not counted, status on record: ${flagged.map(id => `${esc(nameOf(id, S))} (${esc(stOf2(id))})`).join('; ')}.` : ''}</div>`;
  }
  // rival academy teams (from Month 9 or at Kingdom tier)
  let rivals = '';
  if (idx >= 2 || S.World.Month >= 9) {
    const g = _.groupBy(Object.keys(DATA.npcs).filter(id => /team$/.test(DATA.npcs[id].g)), id => DATA.npcs[id].g);
    rivals = `<h3>Rival academies</h3>${Object.entries(g).map(([name, ids]) => `<div class="item"><b>${esc(name)}</b><div class="meta">${ids.map(id => `<button class="who" data-open="npc:${esc(id)}">${avatar(id, S, 'av xs')}<span>${esc(nameOf(id, S))}${DATA.npcs[id].tr ? ` · ${DATA.npcs[id].tr}` : ''}</span></button>`).join('')}</div></div>`).join('')}`;
  }
  return `${status}<h3>The ladder</h3><ol class="ladder">${ladder}</ol>${team}${rivals}`;
}

// ---------------------------------------------------------------- shop
function acShop(S) {
  const W = S.Player.Wallet, items = DATA.shop || [];
  const shops = ['All', ...new Set(items.map(i => i.shop.split(' — ')[0]))];
  if (!shops.includes(view.shop)) view.shop = 'All';
  const list = items.filter(i => view.shop === 'All' || i.shop.split(' — ')[0] === view.shop);
  const bazaar = eventDay(/^Academy Bazaar/), bn = bazaar ? daysTo(S, bazaar.di) : 99;
  const season = SEASON_OF(S.World.Month);   // 1.1.0 (spec §4.9): off-season items are greyed out
  const rows = list.map(i => {
    const at = hereIs(S, i.loc), place = (DATA.locs[i.loc] || { name: i.shop }).name;
    const oos = Array.isArray(i.season) && !i.season.includes(season);
    const afford = !oos && (i.price == null || W.Points >= i.price);
    const text = i.price == null ? `I ask at the ${place} about a special order: ` : at ? `I buy ${aan(i.item.replace(/^The /, 'the '))} for ${i.price} points.` : `I head to ${/^the /i.test(place) ? place : 'the ' + place} to buy ${aan(i.item.replace(/^The /, 'the '))} (${i.price} points).`;
    return `<tr${oos ? ' class="oos"' : ''}><td><b>${esc(i.item)}</b>${oos ? ` <span class="pill oos">out of season</span>` : Array.isArray(i.season) ? ` <span class="pill">${esc(i.season.join(', '))}</span>` : ''}${i.note ? `<div class="sub">${esc(i.note)}</div>` : ''}<div class="sub mw">${esc(i.shop)}</div></td><td class="sub">${esc(i.shop)}</td>
      <td class="pz">${i.price == null ? '—' : fmt(i.price)}${i.canon ? '' : '<span class="gp" title="Guide price">*</span>'}</td>
      <td><button class="btn sm" data-fill="${esc(text)}" ${afford ? '' : `disabled title="${oos ? 'Out of season' : 'Not enough points'}"`}>${at ? 'Buy' : 'Go buy'}</button></td></tr>`;
  }).join('');
  return `<div class="bal"><span><b>${fmt(W.Points)}</b> points</span><span><b>${fmt(W.Coin)}</b> coin</span><button class="btn sm" data-fill="I go to the Banking House to exchange points and coin: ">Banking House</button></div>
    <p class="hint">Points pay for everything on campus; coin is real money (1:1 at the Banking House) and the only money that works off campus. A free version of nearly everything exists: the canteen, the common-room kettle, the dorm laundry.</p>
    ${bn >= -2 && bn <= 14 ? `<div class="warn">Academy Bazaar ${bn < 0 ? 'is on now' : bn === 0 ? 'opens today' : `in ${bn} days`} (M9 W2, Thu–Sat): invited traders, prices are whatever they say, haggling expected.</div>` : ''}
    <div class="tog" style="margin:10px 0">${shops.map(s => `<button data-shop="${esc(s)}" class="${view.shop === s ? 'on' : ''}">${esc(s)}</button>`).join('')}</div>
    <div class="scroll"><table class="shop"><tr><th>Item</th><th>Where</th><th>Points</th><th></th></tr>${rows}</table></div>
    <p class="hint">* Guide price; the narrator uses the same list. Buying only drafts the action into your message box.</p>`;
}

// ---------------------------------------------------------------- projects
function acProjects(S) {
  const Pj = Object.entries(S.Projects || {}).sort(([, a], [, b]) => (a.Progress >= 100) - (b.Progress >= 100));
  if (!Pj.length) return '<div class="empty">No projects yet. Brewing, crafting, research and group assignments appear here once they start in the story.</div>';
  return `<p class="lead">Work that takes more than one sitting. Progress only moves when you actually spend time on it in the story.</p>` + Pj.map(([k, p]) => {
    const done = p.Progress >= 100, lid = p.Where ? locIdOf(p.Where) : '';
    return `<div class="item${done ? ' done' : ''}"><div class="row"><span class="t">${esc(k)}</span><span class="pill">${esc(p.Kind)}</span>${done ? '<span class="pill g">done</span>' : p.Due ? `<span class="pill w">due ${esc(p.Due)}</span>` : ''}</div>
      ${p.Goal ? `<div>${esc(p.Goal)}</div>` : ''}<div class="bar"><i style="width:${p.Progress}%;background:${done ? '#3f9f69' : '#b39062'}"></i></div><div class="sub">${p.Progress}%${p.Needs && !done ? ` · still needs: ${esc(p.Needs)}` : ''}</div>
      <div class="meta">${p.With ? peopleIn(p.With, S) : ''}${p.Where ? `<span class="sub">at ${esc(p.Where)}</span>` : ''}
      ${!done ? `<button class="btn sm" data-fill="${esc(`I spend time working on ${k}${p.Where && !hereIs(S, lid) ? ` at ${p.Where}` : ''}: `)}">Work on it</button>` : ''}
      ${lid && !hereIs(S, lid) && !done ? `<button class="btn sm" data-go="${esc(lid)}">Go</button>` : ''}</div></div>`;
  }).join('');
}

// ---------------------------------------------------------------- trips
const TRIP_INFO = [
  { rx: /^Independence Crowning Day/, name: 'Independence Crowning Day: the capital', lines: [
    'Morning: the whole academy flies to the capital by airship.', 'Parade and the King\'s speech, then free time until the afternoon muster: markets, food, sights.',
    'Groups of four only. Uniform all day; the Doves travel along and staff count heads constantly.', 'Points do not work in the capital: carry coin.',
    'Back before dark, passenger lists counted twice. Fireworks over the hills at night; curfew moves to 22:00.'] },
  { rx: /^Academy Trip/, name: 'Academy Trip: Sunreach Bay', lines: [
    'Month 11 Week 3, Monday to Wednesday; all three years. Half a day by airship.', 'Beachfront hotels, four to a room; teachers in the same hotels set a curfew.',
    'Leave the hotel only in groups of four. The day side is allowed; the night side is out of bounds, which some students ignore every year.',
    'Points do not work abroad and Sunreach is expensive: this is what a year of saving is for.'] },
];
function acTrip(S) {
  const T = S.Trip || {}, W = S.Player.Wallet;
  let h = T.Active ? `<div class="item mine"><div class="row"><span class="t">Travelling: ${esc(T.Destination || 'on a trip')}</span><span class="pill g">now</span></div>
    ${T.Companions.length ? `<div class="meta"><span class="sub">Your group</span>${T.Companions.map(id => npcOf(id) ? `<button class="who" data-open="npc:${esc(id)}">${avatar(id, S, 'av xs')}<span>${esc(nameOf(id, S))}</span></button>` : `<span class="who"><span>${esc(id)}</span></span>`).join('')}</div>` : ''}
    ${T.Note ? `<div class="sub">${esc(T.Note)}</div>` : ''}</div>` : '';
  h += `<div class="bal"><span><b>${fmt(W.Coin)}</b> coin to spend off campus</span><button class="btn sm" data-fill="I go to the Banking House to change points into coin for the trip: ">Change points to coin</button></div>`;
  h += TRIP_INFO.map(ti => {
    const d = eventDay(ti.rx), n = d ? daysTo(S, d.di) : null;
    return `<div class="item"><div class="row"><span class="t">${esc(ti.name)}</span>${d ? `<span class="pill${n >= 0 && n <= 14 ? ' w' : ''}">M${d.e.m} W${d.e.w} ${d.e.d[0]} · ${whenLabel(n)}</span>` : ''}</div><ul class="log">${ti.lines.map(l => `<li>${esc(l)}</li>`).join('')}</ul></div>`;
  }).join('');
  return h;
}

// ---------------------------------------------------------------- battle panel (opens from the "In battle" chip)
const isRunning = (t, M) => Object.values(M.Active || {}).some(e => e.Technique === t);
PANELS.battle = {
  live: true,
  render(S) {
    const Bt = S.Battle || {}, V = S.Player.Vitals, M = S.Magic, T = M._Techniques || {}, H = S.Hidden || {};
    const field = featureOn(S, 'battle') && (S.$ui || {}).wxfx === 'full' && ((S.$ui || {}).wx || {}).field;   // 1.1.0: outdoor field line
    const foes = Object.entries(Bt.Combatants || {});
    const fb = (label, cur, max, color) => { const mx = Math.max(max, cur, 1); return `<div class="fbar"><span>${label}</span><div class="bar"><i style="width:${_.clamp(cur / mx * 100, 0, 100)}%;background:${color}"></i></div><b>${fmt(cur)}</b></div>`; };
    const foeH = foes.length ? foes.map(([id, c]) => `<div class="foe">${npcOf(id) ? avatar(id, S, 'av') : `<span class="av fb">${esc(initials(id))}</span>`}<div class="pm"><span class="pn">${esc(nameOf(id, S))}</span>
      ${fb('HP', c.HP, 100, '#c4504a')}${fb('Stamina', c.Stamina, 100, '#d39b37')}${c.Status ? `<div class="sub">${esc(c.Status)}</div>` : ''}</div></div>`).join('') : '<div class="empty">No opponents tracked.</div>';
    const upkeep = Object.values(M.Active || {}).reduce((a, e) => a + num((T[e.Technique] || {}).Upkeep_per_min), 0);
    const act = Object.entries(M.Active || {}).map(([k, e]) => `<span class="pill g">${esc(k)} · ${fmt((T[e.Technique] || {}).Upkeep_per_min || 0)}/min<button class="lnk" data-fill="${esc(`I let ${k} fade. `)}" style="margin-left:6px">end</button></span>`).join('');
    const techs = Object.entries(T).map(([k, t]) => {
      const running = isRunning(k, M);
      const cost = t.Cost_mode === 'hybrid' && running && t.Trigger ? t.Trigger : t.Activation;
      const can = cost <= V.Mana;
      const warn = H._True_magic && t.Hidden ? ' <span class="pill h" title="Using it here may be noticed">hidden</span>' : '';
      return `<div class="tq${can ? '' : ' no'}"><div><b>${esc(k)}</b>${warn}<div class="sub">${esc(MODES[t.Cost_mode])}: ${fmt(cost)} mana${t.Cost_mode !== 'per_use' && !running ? ` + ${fmt(t.Upkeep_per_min)}/min` : ''}${running ? ' (running)' : ''}</div></div>
        ${running && t.Cost_mode === 'sustained' ? '<span class="pill g">active</span>'
          : `<button class="btn sm" data-fill="${esc(running ? `I trigger ${k}: ` : `I use ${k}: `)}" ${can ? '' : 'disabled title="Not enough mana"'}>${running ? 'Trigger' : 'Use'}</button>`}</div>`;
    }).join('');
    return `<div class="dlg" tabindex="-1"><div class="hd"><h2>${Bt.Active ? 'Battle' : 'No fight in progress'}</h2><button class="x" data-act="close" aria-label="Close">×</button></div><div class="bd">
      ${featureOn(S, 'battle') ? '' : '<p class="hint">Battle tracking is off (Student file → Settings → Features); opponents are not tracked.</p>'}
      ${field ? `<div class="fieldl">Field: ${esc(field)}</div>` : ''}<h3>Opponents</h3>${foeH}
      <h3>You</h3>${vbar('Health', V.HP, V.HP_max, '#c4504a', V._Condition)}${vbar('Stamina', V.Stamina, V.Stamina_max, '#d39b37', V._Fatigue)}${vbar('Mana', V.Mana, V.Mana_max, '#5b8fd4', upkeep ? `Upkeep −${fmt(upkeep)}/min` : '')}
      ${act ? `<div class="meta">${act}</div>` : ''}
      <h3>Techniques</h3>${techs || '<div class="empty">No techniques. Add them in the Student Builder.</div>'}
      <p class="hint">Buttons only draft your action into the message box; the engine charges mana when the narrator reports the cast.</p></div></div>`;
  },
  click(b) { if (b.dataset.fill) fillChat(b.dataset.fill); },
};



// ---------------------------------------------------------------- wiring
if (typeof eventOn === 'function' && typeof getButtonEvent === 'function') {
  $(() => {
    window.parent.__eldrasilUI = true;
    eventOn('eldrasil:open', target => open(String(target || 'profile')));
    eventOn(getButtonEvent('Student file'), () => open('profile'));
    eventOn(getButtonEvent('Builder'), () => open('builder'));
    eventOn(getButtonEvent('People'), () => open('people'));
    eventOn(getButtonEvent('Map'), () => open('map'));
    eventOn(getButtonEvent('Notebook'), () => open('notebook'));
    eventOn(getButtonEvent('Activities'), () => open('activities'));
    const refresh = _.debounce(() => { if (view.panel === 'profile' || (PANELS[view.panel] && PANELS[view.panel].live)) render(); }, 300);
    ['MESSAGE_RECEIVED', 'MESSAGE_DELETED', 'MESSAGE_SWIPED', 'MESSAGE_UPDATED'].forEach(k => tavern_events[k] && eventOn(tavern_events[k], refresh));
    eventOn(tavern_events.CHAT_CHANGED, () => { draft = null; close(); });
    waitGlobalInitialized('Mvu').then(() => eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => setTimeout(refresh, 400)));
    $(window).on('pagehide', () => { delete window.parent.__eldrasilUI; if (host) host.remove(); });
  });
}
